styles:
.obs-scroller {
      height: 260px;
      overflow: auto;
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      background: var(--is-bg);
      padding: 1rem;
    }
    .obs-spacer {
      height: 100px;
      display: grid;
      place-items: center;
      color: var(--is-text-dim);
      font-size: 0.8rem;
      border: 1px dashed var(--is-border-soft);
      border-radius: var(--is-radius-sm);
      margin-bottom: 0.75rem;
    }
    .obs-card {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1rem 1.1rem;
      margin-bottom: 0.75rem;
      border-radius: var(--is-radius);
      border: 1px solid var(--is-border);
      background: var(--is-bg-elev);
      color: var(--is-text-soft);
      opacity: 0.4;
      transform: translateY(8px);
      transition: opacity 280ms ease, transform 280ms ease, background 280ms ease, border-color 280ms ease, color 280ms ease;
    }
    .obs-card.is-in {
      opacity: 1;
      transform: none;
      background: color-mix(in srgb, var(--is-color-brand) 14%, var(--is-bg-elev));
      border-color: color-mix(in srgb, var(--is-color-brand) 45%, var(--is-border));
      color: var(--is-text);
    }
    .obs-badge {
      flex: 0 0 auto;
      font-size: 0.7rem;
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      padding: 0.25em 0.55em;
      border-radius: 999px;
      background: var(--is-control-bg);
      color: var(--is-text-dim);
    }
    .obs-card.is-in .obs-badge {
      background: var(--is-brand-soft);
      color: var(--is-brand-text);
    }
    .obs-panel {
      border: 1px solid var(--is-border);
      border-radius: var(--is-radius);
      background: var(--is-bg);
      padding: 0.85rem;
    }
    .obs-panel__title {
      font-size: 0.72rem;
      font-weight: 600;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      color: var(--is-text-dim);
      margin-bottom: 0.65rem;
    }
    .obs-target {
      padding: 1rem;
      min-height: 3rem;
      line-height: 1.5;
      background: var(--is-control-bg);
      border: 1px solid var(--is-border-soft);
      border-radius: var(--is-radius-sm);
      color: var(--is-text);
    }
    .obs-target [data-chip] {
      display: inline-block;
      margin-left: 0.35em;
      padding: 0.1em 0.45em;
      border-radius: 999px;
      background: var(--is-brand-soft);
      color: var(--is-brand-text);
      font-size: 0.8em;
    }
    .obs-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-top: 0.75rem;
    }
    .obs-hint {
      margin-top: 0.65rem;
      font-size: 0.85rem;
      color: var(--is-text-soft);
      line-height: 1.45;
    }
    .obs-resize-wrap {
      display: grid;
      gap: 0.75rem;
    }
    .obs-resize-box {
      width: min(100%, 280px);
      height: 140px;
      resize: both;
      overflow: auto;
      padding: 1rem;
      border: 1px dashed var(--is-border);
      border-radius: var(--is-radius);
      background:
        repeating-linear-gradient(45deg,
          color-mix(in srgb, var(--is-border) 35%, transparent) 0 8px,
          transparent 8px 16px),
        var(--is-bg-elev);
      color: var(--is-text);
      font-size: 0.9rem;
      line-height: 1.4;
    }
    .obs-size {
      font-variant-numeric: tabular-nums;
      font-weight: 600;
      color: var(--is-text);
    }
    .obs-uses {
      display: grid;
      gap: 0.55rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .obs-uses li {
      display: grid;
      grid-template-columns: 1.5rem 1fr;
      gap: 0.55rem;
      align-items: start;
      color: var(--is-text-soft);
      font-size: 0.92rem;
      line-height: 1.45;
    }
    .obs-uses is-icon {
      width: 1.15em;
      height: 1.15em;
      color: var(--is-accent);
      margin-top: 0.15em;
    }
    .log .type-in { color: #69db7c; }
    .log .type-out { color: #ffa8a8; }
    .log .type-mut { color: #ffe066; }
    .log .type-res { color: #74c0fc; }
